package br.com.sportconnect.core.designsystem.icon

import androidx.compose.foundation.Image
import androidx.compose.foundation.layout.aspectRatio
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * Logo SportConnect como ImageVector, convertido de docs/assets/logo.svg (05 §2).
 * Simbolo "Quique" (grade 48u) + wordmark Saira Condensed ExtraBold em curvas.
 *
 * - [SCLogo.Horizontal]: simbolo + wordmark grafite (fundos claros).
 * - [SCLogo.HorizontalOnDark]: wordmark em "cal de quadra" (fundos escuros).
 * - [SCLogo.Symbol]: so o simbolo (48x48), para avatar/app icon/favicon.
 *
 * As cores sao de MARCA (fixas) — nao seguem o tema, como manda o manual do logo.
 */
object SCLogo {
    private val Grafite = Color(0xFF191C19)
    private val Cal = Color(0xFFF5FBF6)
    private val Verde = Color(0xFF00E46E)
    private val Laranja = Color(0xFFEE6800)

    private const val BASE = "M12,0H36A12,12 0 0 1 48,12V36A12,12 0 0 1 36,48H12A12,12 0 0 1 0,36V12A12,12 0 0 1 12,0Z"
    private const val MIDLINE = "M7,24L41,24"
    private const val S_PATH = "M30 9.5A8 7.25 0 0 0 24 8A8 8 0 0 0 24 24A8 8 0 0 1 24 40A8 7.25 0 0 1 18 38.5"
    private const val BALL = "M34.25,9.5A3.25,3.25 0 1 1 40.75,9.5A3.25,3.25 0 1 1 34.25,9.5Z"

    private fun ImageVector.Builder.symbol(): ImageVector.Builder = apply {
        addPath(pathData = addPathNodes(BASE), fill = SolidColor(Grafite))
        addPath(pathData = addPathNodes(MIDLINE), stroke = SolidColor(Cal), strokeLineWidth = 2f, strokeLineCap = StrokeCap.Round)
        // "Recorte": traco grosso na cor da base faz o S passar por cima da linha de meio.
        addPath(pathData = addPathNodes(S_PATH), stroke = SolidColor(Grafite), strokeLineWidth = 9.5f, strokeLineCap = StrokeCap.Round)
        addPath(pathData = addPathNodes(S_PATH), stroke = SolidColor(Verde), strokeLineWidth = 5.5f, strokeLineCap = StrokeCap.Round)
        addPath(pathData = addPathNodes(BALL), fill = SolidColor(Laranja))
    }

    private fun horizontal(name: String, wordmark: Color): ImageVector =
        ImageVector.Builder(name = name, defaultWidth = 310.dp, defaultHeight = 64.dp, viewportWidth = 310f, viewportHeight = 64f)
            .addGroup(scaleX = 64f / 48f, scaleY = 64f / 48f)
            .symbol()
            .clearGroup()
            .addPath(pathData = addPathNodes(WordmarkPath), fill = SolidColor(wordmark))
            .build()

    val Horizontal: ImageVector by lazy { horizontal("SCLogo.Horizontal", Grafite) }
    val HorizontalOnDark: ImageVector by lazy { horizontal("SCLogo.HorizontalOnDark", Cal) }
    val Symbol: ImageVector by lazy {
        ImageVector.Builder(name = "SCLogo.Symbol", defaultWidth = 48.dp, defaultHeight = 48.dp, viewportWidth = 48f, viewportHeight = 48f)
            .symbol()
            .build()
    }
}

/** Logo horizontal com nome acessivel "SportConnect". */
@Composable
fun SCLogo(
    modifier: Modifier = Modifier,
    onDark: Boolean = false,
    contentDescription: String? = "SportConnect",
) {
    Image(
        imageVector = if (onDark) SCLogo.HorizontalOnDark else SCLogo.Horizontal,
        contentDescription = contentDescription,
        modifier = modifier.aspectRatio(310f / 64f),
    )
}

